{
  "states": ["AUTHORIZATION", "TRANSACTION", "UPDATE"],
  "transitions": [
    {
      "from": "AUTHORIZATION",
      "event": "USER/PASS or APOP",
      "action": "authenticate successfully",
      "to": "TRANSACTION"
    },
    {
      "from": "AUTHORIZATION",
      "event": "QUIT",
      "action": "close connection",
      "to": "UPDATE"
    },
    {
      "from": "TRANSACTION",
      "event": "QUIT",
      "action": "enter UPDATE state",
      "to": "UPDATE"
    },
    {
      "from": "TRANSACTION",
      "event": "RSET",
      "action": "unmark deleted messages",
      "to": "TRANSACTION"
    },
    {
      "from": "TRANSACTION",
      "event": "DELE",
      "action": "mark message as deleted",
      "to": "TRANSACTION"
    },
    {
      "from": "TRANSACTION",
      "event": "NOOP",
      "action": "",
      "to": "TRANSACTION"
    },
